const VERSION_12_SAVE_KEY='sechser.saves.v3';
readSlots=function(){try{const data=JSON.parse(localStorage.getItem(VERSION_12_SAVE_KEY)||'[]');if(!Array.isArray(data))throw Error();storageFailed=false;return data.filter(slot=>slot?.schema===3&&slot.world)}catch{storageFailed=true;return[]}};
persistSlots=function(slots){try{localStorage.setItem(VERSION_12_SAVE_KEY,JSON.stringify(slots));storageFailed=false;return true}catch{storageFailed=true;alert('Speichern fehlgeschlagen. Bitte freien Browserspeicher prüfen. Dein geöffnetes Spiel bleibt erhalten.');return false}};
const pick=list=>list[Math.floor(Math.random()*list.length)],jitter=(value,spread=7)=>clamp(Math.round(value+(Math.random()*2-1)*spread),25,94);
function nationality(){return pick(nationWeights)}
function uniqueIdentity(){for(let attempt=0;attempt<100;attempt++){const nation=nationality(),data=nationData[nation],name=`${pick(data.first)} ${pick(data.last)}`;if(!usedGeneratedNames.has(name)){usedGeneratedNames.add(name);return{name,nation}}}const nation='AT',name=`Spieler ${usedGeneratedNames.size+1}`;usedGeneratedNames.add(name);return{name,nation}}
function playerIdentity(line,n,age,quality=70,cell=17,role=0){const identity=uniqueIdentity(),type=pick(typeByLine[line]),base=baseByType[type],boost=(quality-70)*.55,player={n,name:identity.name,nation:identity.nation,age,line,cell,role,type,foot:Math.random()<.22?'Links':Math.random()<.08?'Beidfüßig':'Rechts',form:0,fresh:100,history:[],seasons:[]};for(const[key,value]of Object.entries(base))player[key]=jitter(value+boost);return player}
function generatedRoster(quality=70){const layout=[['def',2,26,-1],['def',4,28,-1],['def',5,25,-1],['mid',6,16,0],['mid',7,18,0],['mid',8,17,0],['att',9,7,1],['att',10,8,1]],outfield=layout.map(([line,n,cell,role],index)=>playerIdentity(line,n,18+Math.floor(Math.random()*17),quality,cell,role)),identity=uniqueIdentity(),keeper={n:1,name:identity.name,nation:identity.nation,age:20+Math.floor(Math.random()*15),keeper:true,line:'gk',type:'Torwart',foot:Math.random()<.2?'Links':'Rechts',gk:jitter(77+(quality-70)*.55),pas:jitter(63+(quality-70)*.4),pos:jitter(76+(quality-70)*.5),spd:jitter(50),sta:jitter(78),form:0,fresh:100,history:[],seasons:[]};return{outfield,keeper}}
function safeColor(value,fallback){return/^#[0-9a-f]{6}$/i.test(value||'')?value:fallback}
function luminance(hex){const rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.03928?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722}
function textColor(hex){return luminance(hex)>.48?'#102126':'#ffffff'}
function makeKits(primary,secondary){primary=safeColor(primary,'#c7f36b');secondary=safeColor(secondary,'#142629');return{primary,secondary,home:{main:primary,trim:secondary},away:{main:secondary,trim:primary},keeper:{main:'#e5b56a',trim:'#4a341b'}}}
function makeWorld(primary,secondary,completeHistory){const teams=leagueOpponents.map(base=>{const palette=teamPalettes[base.id],roster=generatedRoster(base.strength);return{id:base.id,name:teamNameList[base.id],strength:base.strength,kits:makeKits(palette.primary,palette.secondary),roster:[roster.keeper,...roster.outfield]}});return{version:1,seed:crypto.randomUUID(),completeHistory,kits:makeKits(primary,secondary),teams}}
function flagSVG(code){const label=nationData[code]?.name||code,common=`viewBox="0 0 24 16" role="img" aria-label="${label}" class="flag-icon"><title>${label}</title>`;const designs={AT:'<path fill="#ed2939" d="M0 0h24v16H0z"/><path fill="#fff" d="M0 5.3h24v5.4H0z"/>',DE:'<path d="M0 0h24v5.33H0z"/><path fill="#d00" d="M0 5.33h24v5.34H0z"/><path fill="#ffce00" d="M0 10.67h24V16H0z"/>',SI:'<path fill="#fff" d="M0 0h24v5.33H0z"/><path fill="#0755a5" d="M0 5.33h24v5.34H0z"/><path fill="#d50000" d="M0 10.67h24V16H0z"/>',HR:'<path fill="#f23" d="M0 0h24v5.33H0z"/><path fill="#fff" d="M0 5.33h24v5.34H0z"/><path fill="#171796" d="M0 10.67h24V16H0z"/>',CZ:'<path fill="#fff" d="M0 0h24v8H0z"/><path fill="#d7141a" d="M0 8h24v8H0z"/><path fill="#11457e" d="M0 0l10 8-10 8z"/>',HU:'<path fill="#ce2939" d="M0 0h24v5.33H0z"/><path fill="#fff" d="M0 5.33h24v5.34H0z"/><path fill="#477050" d="M0 10.67h24V16H0z"/>',IT:'<path fill="#009246" d="M0 0h8v16H0z"/><path fill="#fff" d="M8 0h8v16H8z"/><path fill="#ce2b37" d="M16 0h8v16h-8z"/>',CH:'<path fill="#d52b1e" d="M0 0h24v16H0z"/><path fill="#fff" d="M10 3h4v10h-4z"/><path fill="#fff" d="M7 6h10v4H7z"/>',PL:'<path fill="#fff" d="M0 0h24v8H0z"/><path fill="#dc143c" d="M0 8h24v8H0z"/>',RS:'<path fill="#c6363c" d="M0 0h24v5.33H0z"/><path fill="#0c4076" d="M0 5.33h24v5.34H0z"/><path fill="#fff" d="M0 10.67h24V16H0z"/>'};return`<svg ${common}>${designs[code]||designs.AT}</svg>`}
function clubInitials(name){return name.split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()||'6'}
function crestHTML(name,kits){return`<span class="club-crest" style="--crest-main:${kits.primary};--crest-trim:${kits.secondary};--crest-text:${textColor(kits.primary)}" aria-label="Vereinswappen ${escapeHTML(name)}">${escapeHTML(clubInitials(name))}</span>`}
function kitHTML(kit,label){return`<span class="kit-preview" style="--kit-main:${kit.main};--kit-trim:${kit.trim}" role="img" aria-label="${label}"><i></i></span>`}
function worldTeam(id){return activeSave?.world?.teams?.find(team=>team.id===id)}
function userIsHome(){return userFixture()?.home==='user'}
function currentKits(){if(!activeSave?.world)return makeKits('#c7f36b','#142629');return activeSave.world.kits}
function colorDistance(a,b){const rgb=hex=>[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));const x=rgb(a),y=rgb(b);return Math.sqrt(x.reduce((sum,value,index)=>sum+(value-y[index])**2,0))}
function resolvedMatchKits(){const user=currentKits(),opponent=activeOpponent()?.kits||makeKits('#4aa6d8','#f4f1df');let userKit=userIsHome()?user.home:user.away,opponentKit=userIsHome()?opponent.away:opponent.home;if(colorDistance(userKit.main,opponentKit.main)<105){if(userIsHome())opponentKit=colorDistance(userKit.main,opponent.home.main)>colorDistance(userKit.main,opponent.away.main)?opponent.home:opponent.away;else userKit=colorDistance(user.home.main,opponentKit.main)>colorDistance(user.away.main,opponentKit.main)?user.home:user.away}return{user:userKit,opponent:opponentKit}}
function userMatchKit(){return resolvedMatchKits().user}
function applyClubTheme(){if(!activeSave)return;const kits=currentKits(),matchKit=userMatchKit(),root=document.documentElement;root.style.setProperty('--club-primary',kits.primary);root.style.setProperty('--club-secondary',kits.secondary);root.style.setProperty('--club-text',textColor(kits.primary));root.style.setProperty('--kit-main',matchKit.main);root.style.setProperty('--kit-trim',matchKit.trim);root.style.setProperty('--kit-text',textColor(matchKit.main))}

const v11EnsureChampionship=ensureChampionship;ensureChampionship=function(raw){if(raw?.schema!==3||!raw.world)throw Error('Spielstand gehört nicht zu Version 12.');const slot=v11EnsureChampionship(raw);slot.schema=3;slot.completeHistory=true;for(const player of[slot.keeper,...slot.squad]){player.nation=player.nation||'AT';player.foot=player.foot||'Rechts';player.type=player.type||lineNames[player.line]}for(const team of slot.world.teams)team.kits=team.kits||makeKits(teamPalettes[team.id].primary,teamPalettes[team.id].secondary);return slot};
const v11BlankTable=blankTable;blankTable=function(club){if(!activeSave?.world)return v11BlankTable(club);return[{id:'user',name:club,strength:72},...activeSave.world.teams].map(t=>({id:t.id,name:t.name,strength:t.strength,played:0,w:0,d:0,l:0,gf:0,ga:0,pts:0}))};
teamName=function(id){return id==='user'?activeSave.club:worldTeam(id)?.name||id};activeOpponent=function(){const game=userFixture();return worldTeam(game?(game.home==='user'?game.away:game.home):'hafen')||activeSave.world.teams[0]};
opponentPlayers=function(){const roster=activeOpponent().roster.filter(p=>!p.keeper),pickLine=(line,count)=>roster.filter(p=>p.line===line).slice(0,count),selection=[...pickLine('def',2),...pickLine('mid',2),...pickLine('att',1)],cells=[26,28,16,18,7],roles=[-1,-1,0,0,1];return selection.map((player,index)=>({...structuredClone(player),cell:cells[index],role:roles[index]}))};
function getAwayKeeper(){return structuredClone(activeOpponent().roster.find(p=>p.keeper))}

const colorFields=document.createElement('section');colorFields.className='identity-fields';colorFields.innerHTML=`<h3>Vereinsfarben</h3><div class="color-choices"><label>Hauptfarbe<input id="club-primary" type="color" value="#c7f36b"></label><label>Zweitfarbe<input id="club-secondary" type="color" value="#142629"></label></div><div id="identity-preview" class="identity-preview"></div><div class="color-presets"><button type="button" data-colors="#c7f36b,#142629">Limette</button><button type="button" data-colors="#dc3f4d,#f3e9d2">Rot</button><button type="button" data-colors="#3178c6,#f4f0df">Blau</button><button type="button" data-colors="#7a4bc2,#ffcf4a">Violett</button></div></section>`;$('#club-name').insertAdjacentElement('afterend',colorFields);
function updateIdentityPreview(){const name=$('#club-name').value.trim()||'Dein Verein',kits=makeKits($('#club-primary').value,$('#club-secondary').value);$('#identity-preview').innerHTML=`${crestHTML(name,kits)}<div><b>${escapeHTML(name)}</b><span>${kitHTML(kits.home,'Heimtrikot')} Heim&nbsp;&nbsp;${kitHTML(kits.away,'Auswärtstrikot')} Auswärts</span></div>`}
for(const id of['#club-name','#club-primary','#club-secondary'])$(id).addEventListener('input',updateIdentityPreview);$$('[data-colors]').forEach(button=>button.onclick=()=>{const[primary,secondary]=button.dataset.colors.split(',');$('#club-primary').value=primary;$('#club-secondary').value=secondary;updateIdentityPreview()});updateIdentityPreview();
$('#club-form').onsubmit=event=>{event.preventDefault();const name=$('#club-name').value.trim();if(!name)return;const slots=readSlots();if(storageFailed)return;usedGeneratedNames.clear();const own=generatedRoster(72),world=makeWorld($('#club-primary').value,$('#club-secondary').value,true),lineup=[2,4,6,7,9],slot=ensureChampionship({schema:3,id:crypto.randomUUID(),club:name,games:0,updated:new Date().toISOString(),players:own.outfield.filter(p=>lineup.includes(p.n)),squad:own.outfield,keeper:own.keeper,lineup,formation:'balanced',press:0,direct:0,world,completeHistory:true,seasonNumber:1,currentRound:0,schedule:makeSchedule(),table:[{id:'user',name,strength:72},...world.teams].map(t=>({id:t.id,name:t.name,strength:t.strength,played:0,w:0,d:0,l:0,gf:0,ga:0,pts:0}))});if(persistSlots([...slots,slot])){$('#club-form').hidden=true;openSlot(slot)}};

const v11PlayerHistory=playerHistory;playerHistory=function(player){const html=v11PlayerHistory(player),identity=`${flagSVG(player.nation)}<span class="identity-copy">${escapeHTML(player.type||lineNames[player.line])} · ${escapeHTML(player.foot||'Rechts')}fuß</span>`;return html.replace('<h4>Aktuelle Saison',`<div class="player-identity">${identity}</div><h4>Aktuelle Saison`)};
function decorateCenter(){applyClubTheme();const intro=clubCenter.querySelector('.intro>div');if(intro&&!intro.querySelector('.club-crest'))intro.insertAdjacentHTML('afterbegin',crestHTML(activeSave.club,currentKits()));clubCenter.querySelectorAll('.squad-row').forEach((row,index)=>{const player=[activeSave.keeper,...activeSave.squad][index],target=row.querySelector('div');if(player&&target&&!target.querySelector('.flag-icon'))target.insertAdjacentHTML('afterbegin',flagSVG(player.nation))});const footer=clubCenter.querySelector('footer span');if(footer)footer.textContent='Doppel 6 / PROTOTYP 39';if(activeSave.completeHistory===false){const lead=clubCenter.querySelector('.center-lead .help');if(lead)lead.insertAdjacentHTML('afterend','<p class="legacy-note">Vereinshistorie beginnt nur bei einem neu gegründeten Verein.</p>')}}
const v11RenderCenter=renderCenter;renderCenter=function(){v11RenderCenter();decorateCenter()};const v11OpenSlot=openSlot;openSlot=function(raw){v11OpenSlot(raw);applyClubTheme()};function updateSetupKeeper(){const marker=document.querySelector('.keeper');if(!marker||!activeSave)return;marker.querySelector('b').textContent=activeSave.keeper.n;marker.querySelector('span').textContent=`${activeSave.keeper.name.split(' ').slice(-1)[0].toUpperCase()} · TW`}const v11ShowTactics=showTactics;showTactics=function(){v11ShowTactics();applyClubTheme();updateSetupKeeper()};const v11Start=start;start=function(){applyClubTheme();const fixtureKits=resolvedMatchKits(),userKeeper=currentKits().keeper,opponentKeeper=activeOpponent().kits.keeper;v11Start();if(match)match.kits={user:structuredClone(fixtureKits.user),opponent:structuredClone(fixtureKits.opponent),userKeeper:structuredClone(userKeeper),opponentKeeper:structuredClone(opponentKeeper)}};$('#start').onclick=()=>start();

function matchKit(team){const kits=match?.kits||resolvedMatchKits();return team===0?kits.user:kits.opponent}
draw=function(){const c=$('#canvas'),ctx=c.getContext('2d'),w=600,h=740;ctx.clearRect(0,0,w,h);for(let i=0;i<10;i++){ctx.fillStyle=i%2?'#245446':'#214e43';ctx.fillRect(0,i*h/10,w,h/10)}ctx.strokeStyle='#b5d7ba88';ctx.lineWidth=2;ctx.strokeRect(28,26,w-56,h-52);ctx.beginPath();ctx.moveTo(28,h/2);ctx.lineTo(w-28,h/2);ctx.stroke();ctx.beginPath();ctx.arc(w/2,h/2,70,0,Math.PI*2);ctx.stroke();ctx.strokeRect(w*.25,26,w*.5,105);ctx.strokeRect(w*.25,h-131,w*.5,105);ctx.strokeRect(w*.4,10,w*.2,16);ctx.strokeRect(w*.4,h-26,w*.2,16);for(const p of match.people){const x=p.x*w,y=p.y*h,kit=p.keeper?(p.t===0?(match.kits?.userKeeper||currentKits().keeper):(match.kits?.opponentKeeper||activeOpponent().kits.keeper)):matchKit(p.t);if(p===match.owner){ctx.strokeStyle='#fff9';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,23+Math.sin(match.elapsed*6)*2,0,Math.PI*2);ctx.stroke()}ctx.fillStyle='#0003';ctx.beginPath();ctx.ellipse(x,y+9,19,13,0,0,Math.PI*2);ctx.fill();ctx.save();ctx.beginPath();ctx.arc(x,y,17,0,Math.PI*2);ctx.clip();ctx.fillStyle=kit.main;ctx.fillRect(x-18,y-18,36,36);ctx.fillStyle=kit.trim;ctx.fillRect(x-4,y-18,8,36);ctx.restore();ctx.strokeStyle=kit.trim;ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,17,0,Math.PI*2);ctx.stroke();ctx.fillStyle=textColor(kit.trim);ctx.font='bold 15px Arial';ctx.textAlign='center';ctx.fillText(p.n,x,y+6);ctx.fillStyle='#edf7ee';ctx.font='12px Arial';ctx.fillText(p.name.split(' ').slice(-1)[0],x,y+33)}const b=match.ball;ctx.fillStyle='#0005';ctx.beginPath();ctx.arc(b.x*w+2,b.y*h+3,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.strokeStyle='#17292b';ctx.beginPath();ctx.arc(b.x*w,b.y*h,6,0,Math.PI*2);ctx.fill();ctx.stroke()};

document.querySelectorAll('footer span:first-child').forEach(el=>el.textContent='Doppel 6 / PROTOTYP 39');drawSlots();
